public class Counter {
    private int count = 0;

    // Synchronized method — locks on 'this'
    public synchronized void increment() {
        count++;
    }

    // Equivalent synchronized block
    public void decrement() {
        synchronized (this) {
            count--;
        }
    }

    public synchronized int getCount() { return count; }
}

// Static synchronization — locks on Class object
public class StaticCounter {
    private static int count = 0;

    public static synchronized void increment() {
        count++;
    }
}

// Volatile — visibility guarantee
class Flag {
    private volatile boolean running = true;

    public void stop() { running = false; } // write visible to all threads
    public void run() {
        while (running) { /* work */ } // always sees latest value
    }
}

ExecutorService:
import java.util.concurrent.*;

// Fixed thread pool
ExecutorService executor = Executors.newFixedThreadPool(4);

// Submit Runnable
executor.execute(() -> System.out.println("Task 1"));

// Submit Callable (returns result)
Future<Integer> future = executor.submit(() -> {
    Thread.sleep(1000);
    return 42;
});

// Get result (blocks until done)
System.out.println("Result: " + future.get(2, TimeUnit.SECONDS));

// InvokeAll — multiple tasks
List<Callable<String>> tasks = List.of(
    () -> "Task A",
    () -> "Task B",
    () -> "Task C"
);
List<Future<String>> results = executor.invokeAll(tasks);

// Scheduled tasks
ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
scheduler.schedule(() -> System.out.println("Delayed"), 1, TimeUnit.SECONDS);
scheduler.scheduleAtFixedRate(
    () -> System.out.println("Periodic"), 0, 500, TimeUnit.MILLISECONDS);

// Shutdown
executor.shutdown();
try { executor.awaitTermination(5, TimeUnit.SECONDS); }
catch (InterruptedException e) { executor.shutdownNow(); }

CompletableFuture:
import java.util.concurrent.*;

// Supply async
CompletableFuture<String> fetchUser = CompletableFuture.supplyAsync(() -> {
    try { Thread.sleep(500); } catch (InterruptedException e) { }
    return "Alice";
});

// Chain transformations
CompletableFuture<String> greeting = fetchUser
    .thenApply(name -> "Hello, " + name + "!")
    .thenApply(String::toUpperCase);

System.out.println(greeting.get()); // "HELLO, ALICE!"

// Combine two async tasks
CompletableFuture<Integer> price = CompletableFuture.supplyAsync(() -> 100);
CompletableFuture<Integer> discount = CompletableFuture.supplyAsync(() -> 20);
CompletableFuture<Integer> total = price.thenCombine(discount, (p, d) -> p - d);
System.out.println(total.get()); // 80

// All of (parallel execution)
CompletableFuture<String> f1 = CompletableFuture.supplyAsync(() -> "A");
CompletableFuture<String> f2 = CompletableFuture.supplyAsync(() -> "B");
CompletableFuture<Void> all = CompletableFuture.allOf(f1, f2);
all.thenRun(() -> System.out.println("Both done"));

// Error handling
CompletableFuture.supplyAsync(() -> {
    if (true) throw new RuntimeException("Oops");
    return "OK";
}).exceptionally(ex -> "Fallback: " + ex.getMessage())
  .thenAccept(System.out::println);

Atomic Variables & Locks:
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import java.util.stream.IntStream;

// AtomicInteger — lock-free counter
AtomicInteger counter = new AtomicInteger(0);
IntStream.range(0, 10_000).parallel().forEach(i -> counter.incrementAndGet());
System.out.println(counter.get()); // 10000 (correct, no race condition)

// LongAdder (better for high contention)
LongAdder adder = new LongAdder();
IntStream.range(0, 100_000).parallel().forEach(i -> adder.add(1));
System.out.println(adder.sum()); // 100000

// ReentrantLock
Lock lock = new ReentrantLock(true); // fair = true
lock.lock();
try {
    // critical section
} finally {
    lock.unlock(); // always unlock in finally
}

// tryLock — non-blocking attempt
if (lock.tryLock()) {
    try {
        // critical section
    } finally {
        lock.unlock();
    }
} else {
    System.out.println("Could not acquire lock");
}

Virtual Threads:
import java.util.concurrent.*;

// Creating virtual threads
Thread vThread = Thread.ofVirtual().start(() -> {
    System.out.println("Running on: " + Thread.currentThread());
});
vThread.join();

// Virtual thread executor
ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor();

try (executor) {
    for (int i = 0; i < 100_000; i++) {
        int taskId = i;
        executor.submit(() -> {
            try { Thread.sleep(10); } catch (InterruptedException e) { }
            System.out.println("Task " + taskId + " done");
        });
    }
} // millions of virtual threads! only ~OS threads used

// Best practices:
// - Use for I/O-bound tasks, not CPU-bound
// - Prefer ReentrantLock over synchronized (avoids pinning)
// - Use Executors.newVirtualThreadPerTaskExecutor()
// - Available in Java 21+ as production feature
